const int maxn = 2e5 + 5;
int n, q;

int l[maxn], r[maxn], ans[maxn];

vector<int> t[maxn];

pair<int, int> q_[maxn];

int a[maxn];

vector<int> by_val[maxn];

struct BIT {
    int bit[maxn];
    BIT() {
        for (int i = 0; i < maxn; i++) {
            bit[i] = 0;
        }
    }
    void update(int i, int v) {
        while (i < maxn) {
            bit[i] += v;
            i += i & -i;
        }
    }
    int getsum(int i) {
        int sum = 0;
        while (i > 0) {
            sum += bit[i];
            i -= i & -i;
        }
        return sum;
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> q;
    int max_val = 0;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        by_val[a[i]].push_back(i);
        max_val = max(max_val, a[i]); 
    }

    for (int i = 1; i <= q; i++) {
        cin >> q_[i].first >> q_[i].second;
        l[i] = 1;
        r[i] = max_val; 
        ans[i] = max_val;
    }

    bool changed = true;
    while (changed) {
        changed = false;

        for (int i = 1; i <= max_val; i++) t[i].clear();

        for (int i = 1; i <= q; i++) {
            if (l[i] <= r[i]) {
                changed = true;
                int mid = l[i] + (r[i] - l[i]) / 2;
                t[mid].push_back(i);
            }
        }

        if (!changed) break;

        BIT tmp;

        for (int v = 1; v <= max_val; v++) {
            for (int pos : by_val[v]) {
                tmp.update(pos, 1);
            }

            for (int q_idx : t[v]) {
                int L = q_[q_idx].first;
                int R = q_[q_idx].second;
                int len = R - L + 1;

                int needed = (len + 1) / 2;

                int count = tmp.getsum(R) - tmp.getsum(L - 1);

                if (count >= needed) {
                    ans[q_idx] = v;
                    r[q_idx] = v - 1;
                } else {
                    l[q_idx] = v + 1;
                }
            }
        }
    }

    for (int i = 1; i <= q; i++) {
        cout << ans[i] << '\n';
    }

    return 0;
}